from collections import Counter

GROUP_PRICE = {1: 800, 2: 1520, 3: 2160, 4: 2560, 5: 3000}

def total_greedy(basket):
    counts = Counter(basket)
    groups = []
    while counts:
        # take one of each remaining book
        group_size = len(counts)
        groups.append(group_size)
        for k in list(counts.keys()):
            counts[k] -= 1
            if counts[k] == 0:
                del counts[k]

    # count how many groups of each size
    g_counts = Counter(groups)
    # Each pair of (5, 3) can be replaced by (4, 4)
    replace = min(g_counts[5], g_counts[3])
    g_counts[5] -= replace
    g_counts[3] -= replace
    g_counts[4] += 2 * replace

    return sum(GROUP_PRICE[size] * count for size, count in g_counts.items())

from functools import lru_cache
@lru_cache(maxsize=None)
def cost_sorted(counts):
    counts = tuple(sorted((c for c in counts if c > 0), reverse=True))
    if not counts:
        return 0
    best = None
    for k in range(1, len(counts) + 1):
        rem = list(counts)
        for i in range(k):
            rem[i] -= 1
        p = (None, 800, 1520, 2160, 2560, 3000)[k] + cost_sorted(tuple(rem))
        if best is None or p < best:
            best = p
    return best

import itertools
mismatches = 0
for c in itertools.product(range(10), repeat=5):
    basket = []
    for book_id, count in enumerate(c, 1):
        basket.extend([book_id] * count)
    ans_greedy = total_greedy(basket)
    ans_dp = cost_sorted(tuple(c))
    if ans_greedy != ans_dp:
        print(f"Mismatch for {c}: greedy={ans_greedy}, dp={ans_dp}")
        mismatches += 1
        if mismatches > 5:
            break

print(f"Done testing 100,000 cases! Mismatches: {mismatches}")
